"""Shader-only masked candidate fill; original seed/artist PNG bytes untouched."""
import bpy,json,hashlib
from pathlib import Path
def apply(folder):
 folder=Path(folder);cfg=json.loads((folder/'fill-runtime.json').read_text());sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest();paths={'generated':folder/cfg['authored_file'],'binary':folder/'Crown_S_MissingPaintFill_MASK.png','feather':folder/'Crown_S_MissingPaintFeather_DATA.png'}
 assert sha(paths['generated'])==cfg['authored_sha256'];assert sha(paths['binary'])==cfg['binary_mask_sha256'];assert sha(paths['feather'])==cfg['feather_mask_sha256'];assert sha(folder/'Crown_S_ExistingPigment_Bake.png')==cfg['seed_sha256']
 ob=bpy.data.objects['MIA_V17_PIXAL_DetailedHair'];slots=[i for i,s in enumerate(ob.material_slots) if s.material and s.material.name.startswith('MIA_v002_S_CrownFlow_ExistingPigment_Bake')];assert len(slots)==1,'Apply on the fresh S seed-bake slot once';slot=slots[0];old=ob.material_slots[slot].material;ma=old.copy();ma.name='MIA_v002_S_CrownFlow_MaskedAuthoredFill';n=ma.node_tree.nodes;l=ma.node_tree.links;uv=n['S_OWNED_CROWN_FLOW_UV'];seed=n['S_OWNED_EXISTING_PIGMENT_BAKE'];grade=n['V002_SOURCE_ASH_GRADE_INPUT'];assert grade.inputs[0].links[0].from_node==seed;out={};images={}
 for key,path in paths.items():
  image=bpy.data.images.load(str(path),check_existing=False);image.name='MIA_v002_S_'+key;image.colorspace_settings.name='sRGB' if key=='generated' else 'Non-Color';image.alpha_mode='CHANNEL_PACKED';image.pack();tex=n.new('ShaderNodeTexImage');tex.name='S_MASKED_FILL_'+key;tex.image=image;tex.interpolation='Closest' if key=='binary' else 'Linear';tex.extension='EXTEND' if key=='generated' else 'CLIP';l.new(uv.outputs[0],tex.inputs['Vector']);out[key]=tex;images[key]=image
 assert list(images['generated'].size)==cfg['actual_authored_dimensions'] and list(images['feather'].size)==[2048,2048] and list(images['binary'].size)==[2048,2048]
 factors={}
 for key in ['binary','feather']:
  sep=n.new('ShaderNodeSeparateColor');sep.name='S_FILL_MASK_RED_'+key;l.new(out[key].outputs['Color'],sep.inputs[0]);factors[key]=sep.outputs['Red']
 gate=n.new('ShaderNodeMath');gate.operation='GREATER_THAN';gate.inputs[1].default_value=.5;l.new(factors['binary'],gate.inputs[0]);weight=n.new('ShaderNodeMath');weight.name='S_PROTECTED_SEED_ZERO_WEIGHT';weight.operation='MULTIPLY';l.new(gate.outputs[0],weight.inputs[0]);l.new(factors['feather'],weight.inputs[1]);mix=n.new('ShaderNodeMixRGB');mix.name='S_GENERATED_ONLY_IN_MISSING_PAINT';l.new(weight.outputs[0],mix.inputs[0]);l.new(seed.outputs['Color'],mix.inputs[1]);l.new(out['generated'].outputs['Color'],mix.inputs[2]);l.new(mix.outputs[0],grade.inputs[0]);ob.material_slots[slot].material=ma
 assert sum(x.type=='UVMAP' for x in n)==1 and sum(x.type=='ATTRIBUTE' for x in n)==0 and sum(x.type=='TEX_IMAGE' for x in n)==4
 return {'variant':'S original candidate masked fill','slot':slot,'old_material':old.name,'new_material':ma.name,'generated_sha256':cfg['authored_sha256'],'actual_generated_dimensions':cfg['actual_authored_dimensions'],'seed_and_masks_dimensions':[2048,2048],'same_normalized_UV_no_generated_resize':True,'seed_or_generated_pixel_bytes_modified':False,'blend':'Seed*(1-w)+Generated*w; w=Closest(binary>.5)*Linear(numeric4pxinwardfeather). Protected/outside closest-mask0 always forcesw0. Existing K/deformed-geometric-normal/toon route unchanged.','active_UV_streams':1,'active_texture_samplers':4,'legacy240_and_other_face_routes_unchanged':True,'ART':'CANDIDATE_NEEDS_ACTUAL_3D_REVIEW'}
